import { compareJsonNumbers, isJsonNumber } from './jsonNumber.mjs';

export function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

export function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value) && !isJsonNumber(value);
}

export function objectKeys(value) {
  return Object.keys(value);
}

export function clonePath(path, segment) {
  const next = path.slice();
  next.push(segment);
  return next;
}

export function mergeSets(target, source) {
  if (!source) {
    return target;
  }
  const output = target ?? new Set();
  for (const value of source) {
    output.add(value);
  }
  return output;
}

export function mergeResults(target, source) {
  target.errors.push(...source.errors);
  target.evaluatedProperties = mergeSets(target.evaluatedProperties, source.evaluatedProperties);
  target.evaluatedItems = mergeSets(target.evaluatedItems, source.evaluatedItems);
  return target;
}

export function countCodePoints(value) {
  return Array.from(value).length;
}

export function deepEqual(left, right) {
  if (isJsonNumber(left) && isJsonNumber(right)) {
    return compareJsonNumbers(left, right) === 0;
  }
  if (isJsonNumber(left) || isJsonNumber(right)) {
    return false;
  }
  if (left === right) {
    return true;
  }
  if (left === null || right === null) {
    return left === right;
  }
  if (Array.isArray(left) && Array.isArray(right)) {
    if (left.length !== right.length) {
      return false;
    }
    for (let index = 0; index < left.length; index += 1) {
      if (!deepEqual(left[index], right[index])) {
        return false;
      }
    }
    return true;
  }
  if (isPlainObject(left) && isPlainObject(right)) {
    const leftKeys = objectKeys(left);
    const rightKeys = objectKeys(right);
    if (leftKeys.length !== rightKeys.length) {
      return false;
    }
    for (const key of leftKeys) {
      if (!hasOwn(right, key) || !deepEqual(left[key], right[key])) {
        return false;
      }
    }
    return true;
  }
  return false;
}

