import { SchemaError } from './errors.mjs';
import { hasOwn, isPlainObject, objectKeys } from './utils.mjs';

const VALID_TYPES = new Set(['array', 'boolean', 'integer', 'null', 'number', 'object', 'string']);

function describeValue(value) {
  if (value === true) {
    return 'True';
  }
  if (value === false) {
    return 'False';
  }
  if (value === null) {
    return 'null';
  }
  if (isJsonNumber(value)) {
    return value.raw;
  }
  if (typeof value === 'string') {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return 'array';
  }
  if (isPlainObject(value)) {
    return 'object';
  }
  return String(value);
