  ensure(typeof value === 'string', `${describeValue(value)} is not of type 'string' for ${keyword}`);
}

function ensureBoolean(value, keyword) {
  ensure(typeof value === 'boolean', `${describeValue(value)} is not of type 'boolean' for ${keyword}`);
}

function ensureNumber(value, keyword) {
  ensure(isJsonNumber(value), `${describeValue(value)} is not of type 'number' for ${keyword}`);
}

function ensureNonNegativeInteger(value, keyword) {
  ensure(isNonNegativeIntegerToken(value), `${describeValue(value)} is not of type 'integer' for ${keyword}`);
}

