import { DRAFT4, DRAFT6, DRAFT7, DRAFT201909, DRAFT202012, draftForSchema } from './drafts.mjs';
import { BaseValidator } from './validatorEngine.mjs';
import { ErrorTree } from './tree.mjs';
import { UNKNOWN_METASCHEMA_WARNING, printWarning } from './pythonPrint.mjs';

class Draft4Validator extends BaseValidator {
  static __name__ = 'Draft4Validator';

  constructor(schema) {
    super(schema, DRAFT4);
  }
}

class Draft6Validator extends BaseValidator {
  static __name__ = 'Draft6Validator';

  constructor(schema) {
    super(schema, DRAFT6);
  }
}

class Draft7Validator extends BaseValidator {
  static __name__ = 'Draft7Validator';

  constructor(schema) {
    super(schema, DRAFT7);
  }
}

class Draft201909Validator extends BaseValidator {
  static __name__ = 'Draft201909Validator';

  constructor(schema) {
    super(schema, DRAFT201909);
  }
}

class Draft202012Validator extends BaseValidator {
  static __name__ = 'Draft202012Validator';

  constructor(schema) {
    super(schema, DRAFT202012);
  }
}

const DRAFT_TO_CLASS = new Map([
  [DRAFT4, Draft4Validator],
  [DRAFT6, Draft6Validator],
  [DRAFT7, Draft7Validator],
  [DRAFT201909, Draft201909Validator],
  [DRAFT202012, Draft202012Validator],
]);

class FormatChecker {
  constructor() {
    this.checkers = Object.freeze({
      date: true,
      email: true,
      hostname: true,
      'idn-email': true,
      'idn-hostname': true,
      ipv4: true,
      ipv6: true,
      regex: true,
      time: true,
    });
  }
}

const validators = {
  validator_for(schema) {
    const draft = draftForSchema(schema, () => printWarning(UNKNOWN_METASCHEMA_WARNING));
    return DRAFT_TO_CLASS.get(draft) ?? Draft202012Validator;
  },
};

export {
  Draft4Validator,
  Draft6Validator,
  Draft7Validator,
  Draft201909Validator,
  Draft202012Validator,
  ErrorTree,
  FormatChecker,
  validators,
};

