import { JsonNumber } from './jsonNumber.mjs';

class JsonParser {
  constructor(text) {
    this.text = text;
    this.index = 0;
  }

  parse() {
    const value = this.parseValue();
    this.skipWhitespace();
    if (this.index !== this.text.length) {
      this.fail('Extra data');
    }
    return value;
  }

  parseValue() {
    this.skipWhitespace();
    if (this.index >= this.text.length) {
      this.fail('Unexpected end of JSON input');
    }

    const character = this.text[this.index];
    if (character === '"') {
      return this.parseString();
    }
    if (character === '{') {
      return this.parseObject();
    }
    if (character === '[') {
      return this.parseArray();
    }
    if (character === 't') {
      return this.parseLiteral('true', true);
    }
    if (character === 'f') {
      return this.parseLiteral('false', false);
    }
    if (character === 'n') {
      return this.parseLiteral('null', null);
    }
    if (character === '-' || this.isDigit(character)) {
      return this.parseNumber();
    }

    this.fail(`Unexpected token ${character}`);
  }

  parseObject() {
    const result = Object.create(null);
    this.index += 1;
    this.skipWhitespace();

    if (this.text[this.index] === '}') {
      this.index += 1;
      return result;
    }

    while (this.index < this.text.length) {
      this.skipWhitespace();
      if (this.text[this.index] !== '"') {
        this.fail('Expected property name');
      }
      const key = this.parseString();
      this.skipWhitespace();
      if (this.text[this.index] !== ':') {
        this.fail('Expected :');
      }
      this.index += 1;
      result[key] = this.parseValue();
      this.skipWhitespace();
      if (this.text[this.index] === '}') {
        this.index += 1;
        return result;
      }
      if (this.text[this.index] !== ',') {
        this.fail('Expected , or }');
      }
      this.index += 1;
    }

    this.fail('Unterminated object');
  }

  parseArray() {
    const result = [];
    this.index += 1;
    this.skipWhitespace();

    if (this.text[this.index] === ']') {
      this.index += 1;
      return result;
    }

    while (this.index < this.text.length) {
      result.push(this.parseValue());
      this.skipWhitespace();
      if (this.text[this.index] === ']') {
        this.index += 1;
        return result;
      }
      if (this.text[this.index] !== ',') {
        this.fail('Expected , or ]');
      }
      this.index += 1;
    }

    this.fail('Unterminated array');
  }

  parseString() {
    let result = '';
    this.index += 1;

    while (this.index < this.text.length) {
      const character = this.text[this.index];
      if (character === '"') {
        this.index += 1;
        return result;
      }
      if (character === '\\') {
        this.index += 1;
        if (this.index >= this.text.length) {
          this.fail('Unterminated escape sequence');
        }
        const escapeCharacter = this.text[this.index];
        if (escapeCharacter === '"' || escapeCharacter === '\\' || escapeCharacter === '/') {
          result += escapeCharacter;
        } else if (escapeCharacter === 'b') {
          result += '\b';
        } else if (escapeCharacter === 'f') {
          result += '\f';
        } else if (escapeCharacter === 'n') {
          result += '\n';
        } else if (escapeCharacter === 'r') {
          result += '\r';
        } else if (escapeCharacter === 't') {
          result += '\t';
        } else if (escapeCharacter === 'u') {
          const hex = this.text.slice(this.index + 1, this.index + 5);
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) {
            this.fail('Invalid unicode escape');
          }
          result += String.fromCharCode(Number.parseInt(hex, 16));
          this.index += 4;
        } else {
          this.fail('Invalid escape character');
        }
      } else {
        result += character;
      }
      this.index += 1;
    }

    this.fail('Unterminated string');
  }

  parseNumber() {
    const slice = this.text.slice(this.index);
    const match = /^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?/.exec(slice);
    if (!match) {
      this.fail('Invalid number');
    }
    this.index += match[0].length;
    return new JsonNumber(match[0]);
  }

  parseLiteral(literal, value) {
    if (this.text.slice(this.index, this.index + literal.length) !== literal) {
      this.fail(`Unexpected token ${this.text[this.index]}`);
    }
    this.index += literal.length;
    return value;
  }

  skipWhitespace() {
    while (this.index < this.text.length && /\s/.test(this.text[this.index])) {
      this.index += 1;
    }
  }

  isDigit(character) {
    return character >= '0' && character <= '9';
  }

  fail(message) {
    throw new SyntaxError(message);
  }
}

export function parseJson(text) {
  return new JsonParser(text).parse();
}

