const INTEGER_TOKEN_RE = /^-?(0|[1-9]\d*)$/;
const NUMBER_RE = /^(-?)(0|[1-9]\d*)(?:\.(\d+))?(?:[eE]([+-]?\d+))?$/;
const POW10_CACHE = [1n];

function pow10(exponent) {
  while (POW10_CACHE.length <= exponent) {
    POW10_CACHE.push(POW10_CACHE[POW10_CACHE.length - 1] * 10n);
  }
  return POW10_CACHE[exponent];
}

export class JsonNumber {
  constructor(raw) {
    const match = NUMBER_RE.exec(raw);
    if (!match) {
      throw new SyntaxError(`Invalid JSON number: ${raw}`);
    }

    const [, sign, integerPart, fractionPart = '', exponentPart = '0'] = match;
    const exponent = Number(exponentPart);
    const digitsSource = `${integerPart}${fractionPart}`.replace(/^0+(?=\d)/, '') || '0';
    let numerator = BigInt(digitsSource);
    let scale = fractionPart.length - exponent;

    if (sign === '-') {
      numerator = -numerator;
    }
    if (scale < 0) {
      numerator *= pow10(-scale);
      scale = 0;
    }
    if (numerator === 0n) {
      scale = 0;
    } else {
      while (scale > 0 && numerator % 10n === 0n) {
        numerator /= 10n;
        scale -= 1;
      }
    }

    this.raw = raw;
    this.numerator = numerator;
    this.scale = scale;
    this.isIntegerToken = INTEGER_TOKEN_RE.test(raw);
  }
}

export function isJsonNumber(value) {
  return value instanceof JsonNumber;
}

export function compareJsonNumbers(left, right) {
  const scale = Math.max(left.scale, right.scale);
  const leftScaled = left.numerator * pow10(scale - left.scale);
  const rightScaled = right.numerator * pow10(scale - right.scale);

  if (leftScaled < rightScaled) {
    return -1;
  }
  if (leftScaled > rightScaled) {
    return 1;
  }
  return 0;
}

export function jsonNumbersEqual(left, right) {
  return compareJsonNumbers(left, right) === 0;
}

export function isIntegralValue(value) {
  return isJsonNumber(value) && value.scale === 0;
}

export function isNonNegativeIntegerToken(value) {
  return isJsonNumber(value) && value.isIntegerToken && value.numerator >= 0n;
}

export function isPositiveJsonNumber(value) {
  return isJsonNumber(value) && compareJsonNumbers(value, ZERO_NUMBER) > 0;
}

export function isNegativeNumberToken(token) {
  return /^-(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$/.test(token);
}

export function isMultipleOf(instance, divisor) {
  const scale = Math.max(instance.scale, divisor.scale);
  const instanceScaled = instance.numerator * pow10(scale - instance.scale);
  const divisorScaled = divisor.numerator * pow10(scale - divisor.scale);

  if (divisorScaled === 0n) {
    return false;
  }
  return instanceScaled % divisorScaled === 0n;
}

export const ZERO_NUMBER = new JsonNumber('0');

